from pathlib import Path
import json,zipfile,csv,io,hashlib
R=Path(__file__).resolve().parents[3];old=json.loads((R/'tools/evaluation/model-capability/protocol.json').read_text());rows={}
for name,h in old['packs'].items():
 p=R/name;assert hashlib.sha256(p.read_bytes()).hexdigest()==h
 for r in csv.reader(io.StringIO(zipfile.ZipFile(p).read('passages.tsv').decode()),delimiter='\t'):rows[r[0]]=dict(zip(['id','title','url','date','license','text'],r))
def source(prefix):return next(s for k,s in rows.items() if k.startswith(prefix))
items=[
('explanation','Explain how DNA instructions are used to make proteins.',['science-dna-d32'],'Enzymes transcribe DNA information into mRNA; mRNA information is translated into amino-acid order for proteins; preserve both steps.'),
('comparison','Compare genes and DNA sequences outside genes.',['science-dna-160'],'Genes encode protein instructions and comprise about one percent; outside sequences regulate when/how/how much protein is made, not useless DNA.'),
('explanation','Why can a volcano erupt over and over in the same location?',['science-volcanoes-fdd'],'Vent connects through cracks to magma storage; connection to fresh magma enables repeated eruption; not perpetual guaranteed eruption.'),
('qualifier','When can a coronal mass ejection cause a truly large magnetic storm?',['science-magnetic-storms-d3'],'When Earth/Sun field lines directly connect at emission; can, not every ejection inevitably.'),
('comparison','Compare Hetch Hetchy and Wawona in late summer.',['yosemite-341','yosemite-700'],'Hetch Hetchy can be arid/hot in summer; Wawona trails hot/dry in late summer; retain each place and season; no live status.'),
('multisource','How do first-aid supplies and a repair kit prepare for emergencies?',['essentials-b68','essentials-59'],'First-aid kit tailored to medical needs, expiration checks/personal medications; repair tools for equipment specific to trip; do not turn tools into medical treatment.'),
('explanation','What protections apply when private property is taken for public use?',['bill-of-rights-1fd'],'Just compensation required by historical excerpt; do not invent current procedures or amounts.'),
('multisource','How do volcanic vents and wind affect where ash falls?',['science-volcanoes-7e','science-volcanoes-bc'],'Vents emit tephra; ash is tiny tephra transported by wind far away, smallest particles may circle globe before falling; preserve may and size distinction.')]
cases=[{'id':f'new-{i:02}','type':t,'question':q,'sources':[source(p) for p in ids],'expectation':e,'answerable':True} for i,(t,q,ids,e) in enumerate(items,1)]
x={'version':1,'classification':'New public development; real licensed excerpts, never holdout','cases':cases,'packs':old['packs'],'prior_cases_sha256':hashlib.sha256((R/'tools/evaluation/model-capability/protocol.json').read_bytes()).hexdigest(),'evaluation_model':'Qwen3 1.7B Q8 optional candidate, fixed task-200 evaluation anchor; production/demo remains Qwen2.5 0.5B','model_sha256':'061b54daade076b5d3362dac252678d17da8c68f07560be70818cace6590cb1a','execution':'One before run on eight new cases; preserve prior 24-case Qwen3 host run as before reference. One after run on all32. CPU native ISA six threads, fixed production Qwen3 sampling seed42, context2048/output256. No seed/prompt search. Emulator subset cap-02,cap-05,new-01 after host screen, separate timing/outputs.','change':'Remove per-claim character cap and mandatory second claim; allow one through four cited complete sentences under unchanged total token/context bounds. Reject incomplete publication structurally without weakening existing evidence, numeric, conflict or temporal guards.','assessment':'Same task190 builder rubric, source entailment/completeness/usefulness separately; negative quality outcome valid and must remain reported.','emulator_cases':['cap-02','cap-05','new-01']}
p=R/'tools/evaluation/complete-claims/protocol.json';assert not p.exists();p.write_text(json.dumps(x,indent=2)+'\n')
